import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Plan 0015 — task-aware certificates","description":"","frontmatter":{"title":"Plan 0015 — task-aware certificates","type":"plan","date":"2026-10-14T00:00:00.000Z","status_note":"draft — after 0013 groundwork lands."},"headers":[],"relativePath":"graphopt/project/plans/0015-task-aware-certificates.md","filePath":"vendored/graphopt/project/plans/0015-task-aware-certificates.md"}`),a={name:`graphopt/project/plans/0015-task-aware-certificates.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-0015-—-task-aware-certificates" tabindex="-1">Plan 0015 — task-aware certificates <a class="header-anchor" href="#plan-0015-—-task-aware-certificates" aria-label="Permalink to “Plan 0015 — task-aware certificates”">​</a></h1><h2 id="idea" tabindex="-1">Idea <a class="header-anchor" href="#idea" aria-label="Permalink to “Idea”">​</a></h2><p>Today a certificate proves <code>out_opt(x) ≈ out_ref(x)</code> pointwise (exact, or within a propagated bound). But the user&#39;s real contract is the <em>task</em>: for an LLM the logits&#39; ranking matters, not the raw activations; for a classifier the argmax; for retrieval the cosine-ranking of embeddings. A bounded rewrite that preserves the task metric but violates a pointwise bound is wrongly declined today (we measured exactly this in bound_amplification: τ=1e-2 keeps top-1=100% while the propagated bound is loose).</p><h2 id="extension" tabindex="-1">Extension <a class="header-anchor" href="#extension" aria-label="Permalink to “Extension”">​</a></h2><ul><li><code>TaskMetric</code> port (backend-neutral, <code>catopt_core.ports</code>): given (ref_out, opt_out, context) → a scalar distance + pass/fail at a task tolerance. Shipped metrics: <code>TopKAgreement(k)</code>, <code>LogitKL</code>, <code>ArgmaxStability</code>, <code>CosineRanking</code>, <code>MaxRel</code> (the current default).</li><li><code>search(..., task=TopKAgreement(5), task_tol=...)</code> — opt-in; verify gates on the task metric instead of (in addition to) the pointwise bound. Certificate records which task metric accepted, its tolerance, and the measured value — the provenance is still a replayable bound, just expressed in task units.</li><li>The bound ledger stays honest: a task-accepted rewrite records <code>accepted_by=&quot;task&quot;</code>, the pointwise bound is <em>also</em> reported — the two-sided honesty (&quot;certified under task tolerance T, drift measured X&quot;) is the claim.</li></ul><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to “Why it matters”">​</a></h2><p>The amplification study showed the pointwise gate is ~13× conservative — real models have far more exploitable slack than a max_rel gate admits. Task-aware certification is the principled bridge: exploit the slack the task can actually tolerate while staying certified (the certificate says exactly under which task contract the program is equivalent). This is the honest version of &quot;compression knows what matters&quot;.</p><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to “Risks”">​</a></h2><ul><li>Task metrics are input-distribution dependent — the certificate is conditioned on a calibration set (documented, shipped in the manifest); distribution shift is the honest caveat.</li><li>Never silent: <code>stats[&quot;verify_metric&quot;]</code>, manifest records which task metric gated acceptance.</li></ul>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};